cat > /tmp/test_embed.c << 'CEOF'
#define STB_IMAGE_IMPLEMENTATION
#define STB_IMAGE_WRITE_IMPLEMENTATION
#include "stb_image.h"
#include "stb_image_write.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

unsigned char* embed_data(unsigned char *img, int w, int h, int ch,
                          const unsigned char *data, size_t data_len,
                          size_t *out_capacity) {
    size_t total_pixels = w * h;
    size_t total_bits = total_pixels * ch * 8;
    size_t bits_needed = (4 + data_len) * 8;
    if (bits_needed > total_bits) {
        fprintf(stderr, "Not enough capacity: need %zu bits, have %zu bits\n", bits_needed, total_bits);
        return NULL;
    }
    *out_capacity = total_bits / 8;
    unsigned char *stego = malloc(w * h * ch);
    memcpy(stego, img, w * h * ch);

    uint32_t len = (uint32_t)data_len;
    unsigned char len_bytes[4];
    len_bytes[0] = len & 0xFF;
    len_bytes[1] = (len >> 8) & 0xFF;
    len_bytes[2] = (len >> 16) & 0xFF;
    len_bytes[3] = (len >> 24) & 0xFF;

    // DEBUG
    printf("  DEBUG embed: len=%u, len_bytes[0]=0x%02x\n", len, len_bytes[0]);
    printf("  DEBUG embed: first byte bits: ");
    for (int b = 0; b < 8; b++) printf("%d", (len_bytes[0] >> b) & 1);
    printf("\n");
    printf("  DEBUG embed: img[0..7] before: ");
    for (int i = 0; i < 8; i++) printf("%02x ", img[i]);
    printf("\n");

    size_t bit_idx = 0;
    for (int byte = 0; byte < 4; byte++) {
        for (int b = 0; b < 8; b++) {
            size_t pixel_offset = bit_idx / 8;
            int bit = (len_bytes[byte] >> b) & 1;
            if (bit)
                stego[pixel_offset] |= 1;
            else
                stego[pixel_offset] &= ~1;
            bit_idx++;
        }
    }

    printf("  DEBUG embed: stego[0..7] after: ");
    for (int i = 0; i < 8; i++) printf("%02x ", stego[i]);
    printf("\n");
    printf("  DEBUG embed: stego[0..7] LSBs: ");
    for (int i = 0; i < 8; i++) printf("%d ", stego[i] & 1);
    printf("\n");

    for (size_t i = 0; i < data_len; i++) {
        for (int b = 0; b < 8; b++) {
            size_t pixel_offset = bit_idx / 8;
            int bit = (data[i] >> b) & 1;
            if (bit)
                stego[pixel_offset] |= 1;
            else
                stego[pixel_offset] &= ~1;
            bit_idx++;
        }
    }
    return stego;
}

unsigned char* extract_data(unsigned char *img, int w, int h, int ch,
                            size_t *out_len) {
    size_t bit_idx = 0;
    unsigned char len_bytes[4] = {0};
    for (int byte = 0; byte < 4; byte++) {
        for (int b = 0; b < 8; b++) {
            size_t pixel_offset = bit_idx / 8;
            if (pixel_offset >= (size_t)(w * h * ch)) goto fail;
            int bit = img[pixel_offset] & 1;
            len_bytes[byte] |= (bit << b);
            bit_idx++;
        }
    }
    uint32_t data_len = len_bytes[0] | (len_bytes[1]<<8) | (len_bytes[2]<<16) | (len_bytes[3]<<24);

    // DEBUG
    printf("  DEBUG extract: len_bytes = 0x%02x 0x%02x 0x%02x 0x%02x -> data_len=%u\n",
           len_bytes[0], len_bytes[1], len_bytes[2], len_bytes[3], data_len);
    printf("  DEBUG extract: img[0..7] LSBs: ");
    for (int i = 0; i < 8; i++) printf("%d ", img[i] & 1);
    printf("\n");

    if (data_len > (size_t)(w * h * ch) * 8) goto fail;
    unsigned char *data = malloc(data_len);
    for (size_t i = 0; i < data_len; i++) {
        data[i] = 0;
        for (int b = 0; b < 8; b++) {
            size_t pixel_offset = bit_idx / 8;
            if (pixel_offset >= (size_t)(w * h * ch)) goto fail;
            int bit = img[pixel_offset] & 1;
            data[i] |= (bit << b);
            bit_idx++;
        }
    }
    *out_len = data_len;
    return data;
fail:
    *out_len = 0;
    return NULL;
}

int main() {
    int w, h, ch;
    unsigned char *cover = stbi_load("cover1.png", &w, &h, &ch, 0);
    printf("Loaded cover1.png: %dx%d ch=%d\n", w, h, ch);

    // Force RGB like the real code does
    unsigned char *rgb = stbi_load("cover1.png", &w, &h, &ch, 3);
    stbi_image_free(cover);
    cover = rgb;
    ch = 3;
    printf("After RGB force: %dx%d ch=%d\n", w, h, ch);
    printf("  cover[0..7]: ");
    for (int i = 0; i < 8; i++) printf("%02x ", cover[i]);
    printf("\n");

    const char *payload = "Hello World!";
    size_t payload_len = strlen(payload);
    printf("Payload: '%s' (%zu bytes)\n", payload, payload_len);

    size_t capacity;
    unsigned char *stego = embed_data(cover, w, h, ch,
                                      (const unsigned char*)payload, payload_len,
                                      &capacity);
    if (!stego) { fprintf(stderr, "embed failed\n"); return 1; }

    // Save
    char out_name[] = "test_stego.png";
    stbi_write_png(out_name, w, h, ch, stego, w*ch);

    // Reload and extract
    stbi_image_free(cover);

    int w2, h2, ch2;
    unsigned char *reloaded = stbi_load(out_name, &w2, &h2, &ch2, 3);
    printf("Reloaded: %dx%d ch=%d\n", w2, h2, ch2);
    printf("  reloaded[0..7]: ");
    for (int i = 0; i < 8; i++) printf("%02x ", reloaded[i]);
    printf("\n");

    size_t extracted_len;
    unsigned char *extracted = extract_data(reloaded, w2, h2, 3, &extracted_len);
    if (extracted) {
        printf("Extracted %zu bytes: '%.*s'\n", extracted_len, (int)extracted_len, extracted);
        free(extracted);
    } else {
        printf("Extraction failed\n");
    }

    free(stego);
    stbi_image_free(reloaded);
    return 0;
}
