// Write bits: helper used by embed_data
static void write_bits(unsigned char *buf, size_t *bit_idx,
                       const unsigned char *bytes, size_t n) {
    for (size_t i = 0; i < n; i++) {
        for (int b = 0; b < 8; b++) {
            size_t pos = (*bit_idx)++;
            int bit = (bytes[i] >> b) & 1;
            if (bit) buf[pos] |= 1; else buf[pos] &= ~1;
        }
    }
}

// Read bits: helper used by extract_data
static void read_bits(const unsigned char *buf, size_t *bit_idx,
                      unsigned char *bytes, size_t n) {
    for (size_t i = 0; i < n; i++) {
        bytes[i] = 0;
        for (int b = 0; b < 8; b++) {
            size_t pos = (*bit_idx)++;
            int bit = buf[pos] & 1;
            bytes[i] |= (bit << b);
        }
    }
