                          const char *filename, size_t filename_len,
                          const unsigned char *data, size_t data_len,
                          size_t *out_capacity) {
    size_t total_pixels = w * h;
    size_t total_bits = total_pixels * ch * 8;
    size_t bits_needed = (4 + filename_len + 4 + data_len) * 8;

    if (bits_needed > total_bits) {
        fprintf(stderr, "Not enough capacity: need %zu bits, have %zu bits\n", bits_needed, total_bits);
        return NULL;
    }
    *out_capacity = total_bits / 8;

