// Extract data from a stego image.
// Format: fn_len(4) + filename + total_len(4) + chunk_offset(4) + data_len(4) + data
// Returns the raw data, sets *out_filename / *out_filename_len / *out_total_len /
// *out_chunk_offset / *out_data_len.
unsigned char* extract_data(unsigned char *img, int w, int h, int ch,
                            char **out_filename, size_t *out_filename_len,
                            uint32_t *out_total_len, uint32_t *out_chunk_offset,
                            size_t *out_data_len) {
    size_t max_bits = (size_t)w * h * ch;
    size_t bit_idx = 0;

    unsigned char buf[4];
    read_bits(img, &bit_idx, buf, 4);
    if (bit_idx / 8 > max_bits) goto fail;
    uint32_t fn_len = get_u32le(buf);
    if (fn_len > 1024) goto fail;

    char *filename = malloc(fn_len + 1);
    read_bits(img, &bit_idx, (unsigned char*)filename, fn_len);
    if (bit_idx / 8 > max_bits) { free(filename); goto fail; }
    filename[fn_len] = '\0';
    *out_filename = filename;
    *out_filename_len = fn_len;

    read_bits(img, &bit_idx, buf, 4);
    if (bit_idx / 8 > max_bits) goto fail_fn;
    *out_total_len = get_u32le(buf);

    read_bits(img, &bit_idx, buf, 4);
    if (bit_idx / 8 > max_bits) goto fail_fn;
    *out_chunk_offset = get_u32le(buf);

    read_bits(img, &bit_idx, buf, 4);
    if (bit_idx / 8 > max_bits) goto fail_fn;
    uint32_t data_len = get_u32le(buf);
    if (data_len > (size_t)w * h * ch) goto fail_fn;

    unsigned char *data = malloc(data_len);
    read_bits(img, &bit_idx, data, data_len);
    if (bit_idx / 8 > max_bits) { free(data); goto fail_fn; }
    *out_data_len = data_len;
    return data;

fail_fn:
    free(*out_filename);
    *out_filename = NULL;
fail:
    *out_filename = NULL;
    *out_filename_len = 0;
    *out_total_len = 0;
    *out_chunk_offset = 0;
    *out_data_len = 0;
    return NULL;
}

