int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage:\n");
        fprintf(stderr, "  Embed:  %s embed [-p <prefix>] [-o <dir>] <payload> <cover1> [cover2 ...]\n", argv[0]);
        fprintf(stderr, "          (default: 'stego_output/' dir, no prefix; -p <prefix> for naming)\n");
        fprintf(stderr, "  Extract: %s extract [-o <dir>] [-p <prefix>] <stego1> [stego2 ...]\n", argv[0]);
        fprintf(stderr, "          (default: 'extracted/' dir; -p <prefix> for naming)\n");
        return 1;
    }

    if (!strcmp(argv[1], "embed")) {
        const char *prefix = NULL, *out_dir = "stego_output";
        int ai = 2;
        while (ai < argc && argv[ai][0] == '-') {
            if (!strcmp(argv[ai],"-p") && ai+1<argc) { prefix=argv[ai+1]; ai+=2; }
            else if (!strcmp(argv[ai],"-o") && ai+1<argc) { out_dir=argv[ai+1]; ai+=2; }
            else { fprintf(stderr,"Unknown option: %s\n",argv[ai]); return 1; }
        }
        if (argc < ai+2) { fprintf(stderr,"Need payload and at least one cover image\n"); return 1; }

        const char *pf = argv[ai]; FILE *f = fopen(pf,"rb");
        if (!f) { perror(pf); return 1; }
        fseek(f,0,SEEK_END); long fsize=ftell(f); fseek(f,0,SEEK_SET);
        unsigned char *payload=malloc(fsize); fread(payload,1,fsize,f); fclose(f);

        SHA256_CTX sh; sha256_init(&sh); sha256_update(&sh,payload,fsize);
        uint8_t oh[32]; sha256_final(&sh,oh);
        printf("Original payload SHA-256: "); for(int i=0;i<32;i++) printf("%02x",oh[i]); printf("\n");

        const char *bn = strrchr(pf,'/'); bn=bn?bn+1:pf; size_t nl=strlen(bn);
        int nc = argc-ai-1; size_t cs = (fsize+nc-1)/nc, off = 0;
        int use_dir = !prefix; // no prefix => output to directory

        for (int i = 0; i < nc; i++) {
            const char *cp = argv[ai+1+i];
            int w,h,ch; unsigned char *cv = stbi_load(cp,&w,&h,&ch,0);
            if (!cv) { fprintf(stderr,"Cannot load %s\n",cp); return 1; }
            if (ch!=3) { unsigned char *rgb=stbi_load(cp,&w,&h,&ch,3); stbi_image_free(cv); cv=rgb; ch=3; }
            size_t rem=fsize-off, tc=cs; if (tc>rem) tc=rem;
            if (tc==0) { printf("No data left for %s, skipping\n",cp); stbi_image_free(cv); continue; }
            size_t cap; unsigned char *stego = embed_data(cv,w,h,ch,bn,nl,(uint32_t)fsize,(uint32_t)off,payload+off,tc,&cap);
            if (!stego) { fprintf(stderr,"Embedding failed for %s\n",cp); stbi_image_free(cv); return 1; }
            printf("Embedded %zu bytes into %s (capacity %zu bytes)\n",tc,cp,cap);

            // Build output path: dir/prefix<cover> or just <prefix><cover>
            char out[1024];
            const char *cover_bn = strrchr(cp,'/'); cover_bn=cover_bn?cover_bn+1:cp;
            if (use_dir) {
                mkdir(out_dir,0755);
                snprintf(out,sizeof(out),"%s/%s%s",out_dir,prefix?prefix:"",cover_bn);
            } else {
                snprintf(out,sizeof(out),"%s%s",prefix,cover_bn);
            }
            if (!confirm_overwrite(out)) { printf(" -> skipped %s\n",out); free(stego); stbi_image_free(cv); off+=tc; continue; }
            if (!stbi_write_png(out,w,h,ch,stego,w*ch)) { fprintf(stderr,"Failed to write %s\n",out); return 1; }
            printf(" -> saved %s\n",out);
            free(stego); stbi_image_free(cv); off+=tc;
        }
        printf("Embedding complete.\n");

    } else if (!strcmp(argv[1], "extract")) {
        const char *prefix = NULL, *out_dir = "extracted";
        int ai = 2;
        while (ai < argc && argv[ai][0] == '-') {
            if (!strcmp(argv[ai],"-o") && ai+1<argc) { out_dir=argv[ai+1]; ai+=2; }
            else if (!strcmp(argv[ai],"-p") && ai+1<argc) { prefix=argv[ai+1]; ai+=2; }
            else { fprintf(stderr,"Unknown option: %s\n",argv[ai]); return 1; }
        }
        if (argc <= ai) { fprintf(stderr,"Usage: %s extract [-o <dir>] [-p <prefix>] <stego1> [stego2 ...]\n",argv[0]); return 1; }

        struct Chunk *chunks = NULL; int n = 0;
        for (int i = ai; i < argc; i++) {
            int w,h,ch; unsigned char *img = stbi_load(argv[i],&w,&h,&ch,3);
            if (!img) { fprintf(stderr,"Cannot load %s\n",argv[i]); goto cln; }
            char *fn; size_t fnl,dl; uint32_t tot,off;
            unsigned char *d = extract_data(img,w,h,3,&fn,&fnl,&tot,&off,&dl);
            stbi_image_free(img);
            if (!d) { fprintf(stderr,"Failed to extract data from %s\n",argv[i]); goto cln; }
            printf("Extracted %zu bytes from %s (file=%s, offset=%u, total=%u)\n",dl,argv[i],fn,off,tot);
            chunks=realloc(chunks,(n+1)*sizeof(struct Chunk));
            chunks[n].filename=fn; chunks[n].total_len=tot; chunks[n].chunk_offset=off;
            chunks[n].data=d; chunks[n].data_len=dl; n++;
        }
        qsort(chunks,n,sizeof(struct Chunk),chunk_cmp);
        mkdir(out_dir,0755);
        int use_dir = 1; // extract always uses dir (default extracted/)
        int idx = 0;
        while (idx < n) {
            const char *fn = chunks[idx].filename;
            uint32_t total = chunks[idx].total_len;
            int end = idx; uint32_t got = 0; int ok = 1;
            while (end < n && !strcmp(chunks[end].filename,fn)) {
                if (chunks[end].chunk_offset != got) {
                    printf("ERROR: %s — gap at offset %u (expected %u)\n",fn,chunks[end].chunk_offset,got);
                    ok=0; break;
                }
                got += chunks[end].data_len; end++;
            }
            if (ok && got < total) { printf("ERROR: %s — incomplete: got %u of %u bytes\n",fn,got,total); ok=0; }
            if (ok) {
                char out[1024];
                snprintf(out,sizeof(out),"%s/%s%s",out_dir,prefix?prefix:"",fn);
                if (!confirm_overwrite(out)) { printf(" -> skipped %s\n",out); }
                else {
                    printf("Reconstructing '%s' (%u bytes)\n",fn,total);
                    FILE *f = fopen(out,"wb");
                    if (!f) { perror(out); }
                    else {
                        for (int k = idx; k < end; k++) fwrite(chunks[k].data,1,chunks[k].data_len,f);
                        fclose(f);
                        SHA256_CTX sh; sha256_init(&sh);
                        for (int k = idx; k < end; k++) sha256_update(&sh,chunks[k].data,chunks[k].data_len);
                        uint8_t h[32]; sha256_final(&sh,h);
                        printf("  SHA-256: "); for(int k=0;k<32;k++) printf("%02x",h[k]); printf("\n");
                    }
                }
            }
            for (int k = idx; k < end; k++) { free(chunks[k].filename); free(chunks[k].data); }
            idx = end;
        }
        free(chunks);
        if (n==0) { fprintf(stderr,"No data extracted\n"); return 1; }
        return 0;
    cln:
        for (int i = 0; i < n; i++) { free(chunks[i].filename); free(chunks[i].data); }
        free(chunks); return 1;
    } else {
        fprintf(stderr,"Unknown command '%s', use 'embed' or 'extract'\n",argv[1]);
        return 1;
    }
    return 0;
}
