        DIR *d = opendir(folder);
        if (!d) { fprintf(stderr,"Cannot open directory '%s'\n",folder); free(payload); return 1; }
        int n_imgs = 0, cap_arr = 0;
        char **imgs = NULL;
        struct dirent *e;
        while ((e = readdir(d)) != NULL) {
            const char *dot = strrchr(e->d_name, '.');
            if (dot && (!strcasecmp(dot, ".png") || !strcasecmp(dot, ".PNG"))) {
                if (n_imgs == cap_arr) { cap_arr = cap_arr ? cap_arr*2 : 16; imgs = realloc(imgs, cap_arr * sizeof(char*)); }
                size_t plen = strlen(folder) + 1 + strlen(e->d_name) + 1;
                imgs[n_imgs] = malloc(plen);
