            struct stat st;
            if (stat(out_paths[i], &st) != 0) { fprintf(stderr,"Cannot stat %s\n",out_paths[i]); goto fill_fail; }
            if ((size_t)st.st_size > MAX_STEGO_FILE_SIZE) {
                fprintf(stderr,"ERROR: %s exceeds 7.2 MB (%zu bytes) — aborting and cleaning up\n", out_paths[i], (size_t)st.st_size);
                for (int j = 0; j < n_written; j++) { remove(out_paths[j]); free(out_paths[j]); }
                for (int j = 0; j < n_imgs; j++) free(imgs[j]); free(imgs);
                free(out_paths); free(payload); return 1;
            }
        }

        printf("Embedding complete.\n");
        for (int i = 0; i < n_written; i++) {
            struct stat st; stat(out_paths[i], &st);
            printf("  %s (%zu bytes)\n", out_paths[i], (size_t)st.st_size);
            free(out_paths[i]);
        }
        for (int i = 0; i < n_imgs; i++) free(imgs[i]); free(imgs);
        free(out_paths);
