        digest[i+16]=ctx->state[4]>>(24-8*i); digest[i+20]=ctx->state[5]>>(24-8*i);
        digest[i+24]=ctx->state[6]>>(24-8*i); digest[i+28]=ctx->state[7]>>(24-8*i); }
