    uint32_t fnl = get_u32le(b); if (fnl>1024) goto fail;
    char *fn = malloc(fnl+1); read_bits(img,&bi,(unsigned char*)fn,fnl);
    if (bi/8>mb) { free(fn); goto fail; }
    fn[fnl]='\0'; *out_fn=fn; *out_fn_len=fnl;
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    *out_total=get_u32le(b);
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    *out_off=get_u32le(b);
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    uint32_t dl=get_u32le(b); if (dl>(size_t)w*h*ch) goto fail_fn;
    unsigned char *d=malloc(dl); read_bits(img,&bi,d,dl);
    if (bi/8>mb) { free(d); goto fail_fn; }
    *out_dlen=dl; return d;
