            if (ch!=3) { unsigned char *rgb=stbi_load(cp,&w,&h,&ch,3); stbi_image_free(cv); cv=rgb; ch=3; }
            size_t rem=fsize-off, tc=cs; if (tc>rem) tc=rem;
            if (tc==0) { printf("No data left for %s, skipping\n",cp); stbi_image_free(cv); continue; }
            size_t cap; unsigned char *stego = embed_data(cv,w,h,ch,bn,nl,(uint32_t)fsize,(uint32_t)off,payload+off,tc,&cap);
            if (!stego) { fprintf(stderr,"Embedding failed for %s\n",cp); stbi_image_free(cv); goto embed_fail; }
            printf("Embedded %zu bytes into %s (capacity %zu bytes)\n",tc,cp,cap);

            char out[1024];
            const char *cover_bn = strrchr(cp,'/'); cover_bn=cover_bn?cover_bn+1:cp;
            if (use_dir) { mkdir(out_dir,0755); snprintf(out,sizeof(out),"%s/%s%s",out_dir,prefix?prefix:"",cover_bn); }
            else { snprintf(out,sizeof(out),"%s%s",prefix,cover_bn); }
            if (!confirm_overwrite(out)) { printf(" -> skipped %s\n",out); free(stego); stbi_image_free(cv); off+=tc; continue; }
            if (!stbi_write_png(out,w,h,ch,stego,w*ch)) { fprintf(stderr,"Failed to write %s\n",out); free(stego); stbi_image_free(cv); goto embed_fail; }
            out_paths[n_written] = strdup(out);
            n_written++;
            free(stego); stbi_image_free(cv); off+=tc;
        }

        for (int i = 0; i < n_written; i++) {
            struct stat st;
            if (stat(out_paths[i], &st) != 0) { fprintf(stderr,"Cannot stat %s\n",out_paths[i]); goto embed_fail; }
            if ((size_t)st.st_size > MAX_STEGO_FILE_SIZE) {
                fprintf(stderr,"ERROR: %s exceeds 7.2 MB (%zu bytes) — aborting and cleaning up\n", out_paths[i], (size_t)st.st_size);
                for (int j = 0; j < n_written; j++) { remove(out_paths[j]); free(out_paths[j]); }
                free(out_paths); free(payload); return 1;
            }
        }

        printf("Embedding complete.\n");
        for (int i = 0; i < n_written; i++) {
            struct stat st; stat(out_paths[i], &st);
            printf("  %s (%zu bytes)\n", out_paths[i], (size_t)st.st_size);
            free(out_paths[i]);
        }
        free(out_paths);
        return 0;

    embed_fail:
        for (int i = 0; i < n_written; i++) { remove(out_paths[i]); free(out_paths[i]); }
        free(out_paths); free(payload);
        return 1;

    } else if (!strcmp(argv[1], "fill")) {
        const char *prefix = NULL, *out_dir = "stego_output";
        int user_dir = 0, ai = 2;
        while (ai < argc && argv[ai][0] == '-') {
            if (!strcmp(argv[ai],"-p") && ai+1<argc) { prefix=argv[ai+1]; ai+=2; }
            else if (!strcmp(argv[ai],"-o") && ai+1<argc) { out_dir=argv[ai+1]; user_dir=1; ai+=2; }
            else { fprintf(stderr,"Unknown option: %s\n",argv[ai]); return 1; }
