            unsigned char *stego = embed_data(cv,w,h,ch,bn,nl,(uint32_t)fsize,(uint32_t)off,payload+off,tc,&cap_bytes);
            if (!stego) { fprintf(stderr,"Embedding failed for %s\n",cp); stbi_image_free(cv); goto fill_fail; }
            printf("Embedded %zu bytes into %s (capacity %zu bytes)\n",tc,cp,cap_bytes);

