        return 0;

    fill_fail:
        for (int i = 0; i < n_written; i++) { remove(out_paths[i]); free(out_paths[i]); }
        for (int i = 0; i < n_imgs; i++) free(imgs[i]); free(imgs);
        free(out_paths); free(payload);
        return 1;

    } else if (!strcmp(argv[1], "extract")) {
        const char *prefix = NULL, *out_dir = "extracted";
        int user_dir = 0, ai = 2;
        while (ai < argc && argv[ai][0] == '-') {
            if (!strcmp(argv[ai],"-o") && ai+1<argc) { out_dir=argv[ai+1]; user_dir=1; ai+=2; }
            else if (!strcmp(argv[ai],"-p") && ai+1<argc) { prefix=argv[ai+1]; ai+=2; }
            else { fprintf(stderr,"Unknown option: %s\n",argv[ai]); return 1; }
