        for (int i = ai; i < argc; i++) {
            int w,h,ch; unsigned char *img = stbi_load(argv[i],&w,&h,&ch,3);
            if (!img) { fprintf(stderr,"Cannot load %s\n",argv[i]); goto cln; }
            char *fn; size_t fnl,dl; uint32_t tot,off;
            unsigned char *d = extract_data(img,w,h,3,&fn,&fnl,&tot,&off,&dl);
            stbi_image_free(img);
            if (!d) { fprintf(stderr,"Failed to extract data from %s\n",argv[i]); goto cln; }
            printf("Extracted %zu bytes from %s (file=%s, offset=%u, total=%u)\n",dl,argv[i],fn,off,tot);
            chunks=realloc(chunks,(n+1)*sizeof(struct Chunk));
            chunks[n].filename=fn; chunks[n].total_len=tot; chunks[n].chunk_offset=off;
            chunks[n].data=d; chunks[n].data_len=dl; n++;
        }
        qsort(chunks,n,sizeof(struct Chunk),chunk_cmp);
        mkdir(out_dir,0755);
        int use_dir = (user_dir || !prefix);
        int idx = 0;
        while (idx < n) {
            const char *fn = chunks[idx].filename;
            uint32_t total = chunks[idx].total_len;
            int end = idx; uint32_t got = 0; int ok = 1;
            while (end < n && !strcmp(chunks[end].filename,fn)) {
                if (chunks[end].chunk_offset != got) {
                    printf("ERROR: %s — gap at offset %u (expected %u)\n",fn,chunks[end].chunk_offset,got);
                    ok=0; break;
                }
                got += chunks[end].data_len; end++;
            }
            if (ok && got < total) { printf("ERROR: %s — incomplete: got %u of %u bytes\n",fn,got,total); ok=0; }
            if (ok) {
                char out[1024];
                if (use_dir) {
                    snprintf(out,sizeof(out),"%s/%s%s",out_dir,prefix?prefix:"",fn);
                } else {
                    snprintf(out,sizeof(out),"%s%s",prefix,fn);
                }
                if (!confirm_overwrite(out)) { printf(" -> skipped %s\n",out); }
                else {
                    printf("Reconstructing '%s' (%u bytes)\n",fn,total);
                    FILE *f = fopen(out,"wb");
                    if (!f) { perror(out); }
                    else {
                        for (int k = idx; k < end; k++) fwrite(chunks[k].data,1,chunks[k].data_len,f);
                        fclose(f);
                        SHA256_CTX sh; sha256_init(&sh);
                        for (int k = idx; k < end; k++) sha256_update(&sh,chunks[k].data,chunks[k].data_len);
                        uint8_t h[32]; sha256_final(&sh,h);
                        printf("  SHA-256: "); for(int k=0;k<32;k++) printf("%02x",h[k]); printf("\n");
                    }
                }
            }
            for (int k = idx; k < end; k++) { free(chunks[k].filename); free(chunks[k].data); }
            idx = end;
        }
        free(chunks);
        if (n==0) { fprintf(stderr,"No data extracted\n"); return 1; }
        return 0;
    cln:
        for (int i = 0; i < n; i++) { free(chunks[i].filename); free(chunks[i].data); }
        free(chunks); return 1;
    } else {
        fprintf(stderr,"Unknown command '%s', use 'embed', 'fill', or 'extract'\n",argv[1]);
        return 1;
    }
    return 0;
