static int confirm_overwrite(const char *path) {
    if (access(path, F_OK) == -1) return 1;
    fprintf(stderr, "File '%s' exists. Overwrite? [y/N] ", path);
    char buf[16];
    if (!fgets(buf, sizeof(buf), stdin)) return 0;
    return buf[0] == 'y' || buf[0] == 'Y';
}

typedef struct { uint32_t state[8]; uint64_t count; uint8_t buffer[64]; } SHA256_CTX;

#define ROTR(x,n) (((x) >> (n)) | ((x) << (32-(n))))
#define S0(x) (ROTR(x, 2) ^ ROTR(x,13) ^ ROTR(x,22))
#define S1(x) (ROTR(x, 6) ^ ROTR(x,11) ^ ROTR(x,25))
#define s0(x) (ROTR(x, 7) ^ ROTR(x,18) ^ ((x) >> 3))
#define s1(x) (ROTR(x,17) ^ ROTR(x,19) ^ ((x) >> 10))

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static void sha256_transform(SHA256_CTX *ctx, const uint8_t data[]) {
    uint32_t a,b,c,d,e,f,g,h,i,j,t1,t2,m[64];
    for (i=0,j=0; i<16; ++i, j+=4) m[i] = (data[j]<<24)|(data[j+1]<<16)|(data[j+2]<<8)|data[j+3];
    for (; i<64; ++i) m[i] = s1(m[i-2])+m[i-7]+s0(m[i-15])+m[i-16];
    a=ctx->state[0]; b=ctx->state[1]; c=ctx->state[2]; d=ctx->state[3];
    e=ctx->state[4]; f=ctx->state[5]; g=ctx->state[6]; h=ctx->state[7];
    for (i=0; i<64; ++i) {
        t1=h+S1(e)+((e&f)^(~e&g))+K[i]+m[i]; t2=S0(a)+((a&b)^(a&c)^(b&c));
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    ctx->state[0]+=a; ctx->state[1]+=b; ctx->state[2]+=c; ctx->state[3]+=d;
    ctx->state[4]+=e; ctx->state[5]+=f; ctx->state[6]+=g; ctx->state[7]+=h;
}

static void sha256_init(SHA256_CTX *ctx) {
    ctx->count=0; ctx->state[0]=0x6a09e667; ctx->state[1]=0xbb67ae85;
    ctx->state[2]=0x3c6ef372; ctx->state[3]=0xa54ff53a;
    ctx->state[4]=0x510e527f; ctx->state[5]=0x9b05688c;
    ctx->state[6]=0x1f83d9ab; ctx->state[7]=0x5be0cd19;
}

static void sha256_update(SHA256_CTX *ctx, const uint8_t *data, size_t len) {
    size_t i = ctx->count % 64; ctx->count += len;
    while (len--) { ctx->buffer[i++] = *data++; if (i==64) { sha256_transform(ctx, ctx->buffer); i=0; } }
}

static void sha256_final(SHA256_CTX *ctx, uint8_t digest[32]) {
    size_t i = ctx->count % 64; ctx->buffer[i++] = 0x80;
    if (i>56) { while (i<64) ctx->buffer[i++]=0; sha256_transform(ctx,ctx->buffer); i=0; }
    while (i<56) ctx->buffer[i++]=0;
    uint64_t bits = ctx->count*8;
    ctx->buffer[56]=bits>>56; ctx->buffer[57]=bits>>48; ctx->buffer[58]=bits>>40; ctx->buffer[59]=bits>>32;
    ctx->buffer[60]=bits>>24; ctx->buffer[61]=bits>>16; ctx->buffer[62]=bits>>8;  ctx->buffer[63]=bits;
    sha256_transform(ctx, ctx->buffer);
    for (i=0; i<4; ++i) { digest[i]=ctx->state[0]>>(24-8*i); digest[i+4]=ctx->state[1]>>(24-8*i);
        digest[i+8]=ctx->state[2]>>(24-8*i); digest[i+12]=ctx->state[3]>>(24-8*i);
        digest[i+16]=ctx->state[4]>>(24-8*i); digest[i+20]=ctx->state[5]>>(24-8*i);
        digest[i+24]=ctx->state[6]>>(24-8*i); digest[i+28]=ctx->state[7]>>(24-8*i); }
}

static void write_bits(unsigned char *buf, size_t *bit_idx, const unsigned char *bytes, size_t n) {
    for (size_t i = 0; i < n; i++)
        for (int b = 0; b < 8; b++) {
            size_t pos = (*bit_idx)++;
            if ((bytes[i] >> b) & 1) buf[pos] |= 1; else buf[pos] &= ~1;
        }
}

static void read_bits(const unsigned char *buf, size_t *bit_idx, unsigned char *bytes, size_t n) {
    for (size_t i = 0; i < n; i++) {
        bytes[i] = 0;
        for (int b = 0; b < 8; b++) { size_t pos = (*bit_idx)++; bytes[i] |= ((buf[pos] & 1) << b); }
    }
}

static void put_u32le(unsigned char dst[4], uint32_t v) {
    dst[0]=v&0xFF; dst[1]=(v>>8)&0xFF; dst[2]=(v>>16)&0xFF; dst[3]=(v>>24)&0xFF;
}

static uint32_t get_u32le(const unsigned char src[4]) {
    return src[0]|((uint32_t)src[1]<<8)|((uint32_t)src[2]<<16)|((uint32_t)src[3]<<24);
}

struct Chunk { char *filename; uint32_t total_len, chunk_offset; unsigned char *data; size_t data_len; };

static int chunk_cmp(const void *a, const void *b) {
    const struct Chunk *ca=a,*cb=b; int c=strcmp(ca->filename,cb->filename);
    return c?c:(ca->chunk_offset<cb->chunk_offset?-1:(ca->chunk_offset>cb->chunk_offset?1:0));
}

static int name_cmp(const void *a, const void *b) {
    return strcmp(*(const char**)a, *(const char**)b);
}

unsigned char* embed_data(unsigned char *img, int w, int h, int ch,
                          const char *filename, size_t filename_len,
                          uint32_t total_len, uint32_t chunk_offset,
                          const unsigned char *data, size_t data_len,
                          size_t *out_capacity) {
    size_t total = w * h, total_bits = total * ch * 8;
    size_t needed = (4 + filename_len + 4 + 4 + 4 + data_len) * 8;
    if (needed > total_bits) {
        fprintf(stderr, "Not enough capacity: need %zu bits, have %zu bits\n", needed, total_bits);
        return NULL;
    }
    *out_capacity = total_bits / 8;
    unsigned char *stego = malloc(w * h * ch);
    memcpy(stego, img, w * h * ch);
    size_t bi = 0; unsigned char b[4];
    put_u32le(b, (uint32_t)filename_len); write_bits(stego, &bi, b, 4);
    write_bits(stego, &bi, (const unsigned char*)filename, filename_len);
    put_u32le(b, total_len); write_bits(stego, &bi, b, 4);
    put_u32le(b, chunk_offset); write_bits(stego, &bi, b, 4);
    put_u32le(b, (uint32_t)data_len); write_bits(stego, &bi, b, 4);
    write_bits(stego, &bi, data, data_len);
    return stego;
}

unsigned char* extract_data(unsigned char *img, int w, int h, int ch,
                            char **out_fn, size_t *out_fn_len,
                            uint32_t *out_total, uint32_t *out_off,
                            size_t *out_dlen) {
    size_t mb = (size_t)w * h * ch, bi = 0; unsigned char b[4];
    read_bits(img, &bi, b, 4); if (bi/8>mb) goto fail;
    uint32_t fnl = get_u32le(b); if (fnl>1024) goto fail;
    char *fn = malloc(fnl+1); read_bits(img,&bi,(unsigned char*)fn,fnl);
    if (bi/8>mb) { free(fn); goto fail; }
    fn[fnl]='\0'; *out_fn=fn; *out_fn_len=fnl;
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    *out_total=get_u32le(b);
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    *out_off=get_u32le(b);
    read_bits(img,&bi,b,4); if (bi/8>mb) goto fail_fn;
    uint32_t dl=get_u32le(b); if (dl>(size_t)w*h*ch) goto fail_fn;
    unsigned char *d=malloc(dl); read_bits(img,&bi,d,dl);
    if (bi/8>mb) { free(d); goto fail_fn; }
    *out_dlen=dl; return d;
fail_fn: free(*out_fn); *out_fn=NULL;
fail: *out_fn=NULL; *out_fn_len=0; *out_total=0; *out_off=0; *out_dlen=0; return NULL;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "Usage:\n");
        fprintf(stderr, "  Embed:  %s embed [-p <prefix>] [-o <dir>] <payload> <cover1> [cover2 ...]\n", argv[0]);
