} else if (!strcmp(argv[1], "embdir")) {
    const char *prefix = NULL, *out_dir = "stego_output";
    int user_dir = 0, ai = 2;
    while (ai < argc && argv[ai][0] == '-') {
        if (!strcmp(argv[ai],"-p") && ai+1<argc) { prefix=argv[ai+1]; ai+=2; }
        else if (!strcmp(argv[ai],"-o") && ai+1<argc) { out_dir=argv[ai+1]; user_dir=1; ai+=2; }
        else { fprintf(stderr,"Unknown option: %s\n",argv[ai]); return 1; }
    }
    if (argc < ai+2) { fprintf(stderr,"Need files folder and carrier folder\n"); return 1; }

    const char *files_folder = argv[ai];
    const char *carriers_folder = argv[ai+1];

    // Scan carriers folder for .png
    DIR *d = opendir(carriers_folder);
    if (!d) { fprintf(stderr,"Cannot open carrier directory '%s'\n",carriers_folder); return 1; }
    int n_carriers = 0, cap_car = 0;
    char **carriers = NULL;
    struct dirent *e;
    while ((e = readdir(d)) != NULL) {
        const char *dot = strrchr(e->d_name, '.');
        if (dot && (!strcasecmp(dot, ".png") || !strcasecmp(dot, ".PNG"))) {
            if (n_carriers == cap_car) { cap_car = cap_car ? cap_car*2 : 16; carriers = realloc(carriers, cap_car * sizeof(char*)); }
            size_t plen = strlen(carriers_folder) + 1 + strlen(e->d_name) + 1;
            carriers[n_carriers] = malloc(plen);
            snprintf(carriers[n_carriers], plen, "%s/%s", carriers_folder, e->d_name);
            n_carriers++;
        }
    }
    closedir(d);
    if (n_carriers == 0) { fprintf(stderr,"No PNG files in '%s'\n",carriers_folder); free(carriers); return 1; }
    qsort(carriers, n_carriers, sizeof(char*), name_cmp);

    // Scan files folder for all files
    d = opendir(files_folder);
    if (!d) { fprintf(stderr,"Cannot open files directory '%s'\n",files_folder); free_files: for (int i = 0; i < n_carriers; i++) free(carriers[i]); free(carriers); return 1; }
    int n_files = 0, cap_fl = 0;
    char **files = NULL;
    while ((e = readdir(d)) != NULL) {
        if (e->d_name[0] == '.') continue;
        if (n_files == cap_fl) { cap_fl = cap_fl ? cap_fl*2 : 16; files = realloc(files, cap_fl * sizeof(char*)); }
        size_t plen = strlen(files_folder) + 1 + strlen(e->d_name) + 1;
        files[n_files] = malloc(plen);
        snprintf(files[n_files], plen, "%s/%s", files_folder, e->d_name);
        struct stat st;
        if (stat(files[n_files], &st) != 0 || !S_ISREG(st.st_mode)) { free(files[n_files]); continue; }
        n_files++;
    }
    closedir(d);
    if (n_files == 0) { fprintf(stderr,"No files in '%s'\n",files_folder); goto free_files; }
    qsort(files, n_files, sizeof(char*), name_cmp);

    int use_dir = (user_dir || !prefix);
    char **out_paths = malloc(n_carriers * sizeof(char*));
    int n_written_total = 0;
    int file_idx = 0, carrier_idx = 0;
    int any_error = 0;

    for (file_idx = 0; file_idx < n_files; file_idx++) {
        const char *fp = files[file_idx];
        FILE *f = fopen(fp, "rb");
        if (!f) { perror(fp); any_error = 1; break; }
        fseek(f,0,SEEK_END); long fsize = ftell(f); fseek(f,0,SEEK_SET);
        unsigned char *payload = malloc(fsize);
        fread(payload, 1, fsize, f); fclose(f);

        SHA256_CTX sh; sha256_init(&sh); sha256_update(&sh,payload,fsize);
        uint8_t oh[32]; sha256_final(&sh,oh);
        printf("File '%s' SHA-256: ", files[file_idx]); for(int i=0;i<32;i++) printf("%02x",oh[i]); printf(" (%ld bytes)\n",fsize);

        const char *fb = strrchr(fp,'/'); fb=fb?fb+1:fp; size_t fbl = strlen(fb);
        size_t off = 0;
        int batch_start = n_written_total;

        while (off < (size_t)fsize) {
            if (carrier_idx >= n_carriers) {
                fprintf(stderr,"ERROR: ran out of carriers while embedding '%s'\n",fb);
                any_error = 1; break;
            }
            const char *cp = carriers[carrier_idx];
            int w,h,ch; unsigned char *cv = stbi_load(cp,&w,&h,&ch,0);
            if (!cv) { fprintf(stderr,"Cannot load %s\n",cp); any_error = 1; break; }
            if (ch!=3) { unsigned char *rgb=stbi_load(cp,&w,&h,&ch,3); stbi_image_free(cv); cv=rgb; ch=3; }

            size_t max_data = ((size_t)w * h * ch) / 8;
            if (max_data <= 16 + fbl) { stbi_image_free(cv); carrier_idx++; continue; }
            max_data -= 16 + fbl;

            size_t rem = fsize - off;
            size_t tc = rem < max_data ? rem : max_data;
            size_t cap_bytes;
            unsigned char *stego = embed_data(cv,w,h,ch,fb,fbl,(uint32_t)fsize,(uint32_t)off,payload+off,tc,&cap_bytes);
            if (!stego) { fprintf(stderr,"Embedding failed for %s\n",cp); stbi_image_free(cv); any_error = 1; break; }
            printf("  %s +%zu (%s)\n",fb,tc,cp);

            char out[1024];
            const char *cover_bn = strrchr(cp,'/'); cover_bn=cover_bn?cover_bn+1:cp;
            if (use_dir) { mkdir(out_dir,0755); snprintf(out,sizeof(out),"%s/%s%s",out_dir,prefix?prefix:"",cover_bn); }
            else { snprintf(out,sizeof(out),"%s%s",prefix,cover_bn); }
            if (!confirm_overwrite(out)) { printf(" -> skipped %s\n",out); free(stego); stbi_image_free(cv); off+=tc; carrier_idx++; continue; }
            if (!stbi_write_png(out,w,h,ch,stego,w*ch)) { fprintf(stderr,"Failed to write %s\n",out); free(stego); stbi_image_free(cv); any_error = 1; break; }
            out_paths[n_written_total] = strdup(out);
            n_written_total++;
            free(stego); stbi_image_free(cv); off += tc; carrier_idx++;
        }

        free(payload);
        if (any_error) break;

        // Per-file size check
        for (int i = batch_start; i < n_written_total; i++) {
            struct stat st;
            if (stat(out_paths[i], &st) != 0) { fprintf(stderr,"Cannot stat %s\n",out_paths[i]); any_error = 1; break; }
            if ((size_t)st.st_size > MAX_STEGO_FILE_SIZE) {
                fprintf(stderr,"ERROR: %s exceeds 7.2 MB (%zu bytes) — aborting\n", out_paths[i], (size_t)st.st_size);
                for (int j = batch_start; j < n_written_total; j++) { remove(out_paths[j]); free(out_paths[j]); }
                n_written_total = batch_start;
                for (int i = 0; i < n_carriers; i++) free(carriers[i]); free(carriers);
                for (int i = 0; i < n_files; i++) free(files[i]); free(files);
                free(out_paths); return 1;
            }
        }
    }

    if (any_error) {
        // Remove current file's batch only
        for (int i = batch_start; i < n_written_total; i++) { remove(out_paths[i]); free(out_paths[i]); }
        n_written_total = batch_start;
        // Print what was written from previous files
        if (n_written_total > 0) {
            printf("Partially completed.\n");
            for (int i = 0; i < n_written_total; i++) {
                struct stat st; stat(out_paths[i], &st);
                printf("  %s (%zu bytes)\n", out_paths[i], (size_t)st.st_size);
                free(out_paths[i]);
            }
        }
        for (int i = 0; i < n_carriers; i++) free(carriers[i]); free(carriers);
        for (int i = 0; i < n_files; i++) free(files[i]); free(files);
        free(out_paths); return 1;
